    """
    Return True if the brackets in `s` (parentheses (), square brackets [], curly braces {})
    are properly opened, closed, and nested. All other characters are ignored.
    """
    # mapping of closing to opening brackets
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())

    stack = []
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

