    """
    Return True if brackets in the string `s` are properly opened, closed,
    and nested. Only the following brackets are considered: (), [], {}.
    All other characters are ignored.
    """
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())

